Algorithm Alcanza
  Define dinero As Integer <- 10;
  If dinero >= 12 Then
    Write "Alcanza";
  Else
    Write "No alcanza";
  EndIf
EndAlgorithm

Algorithm Cine
  Define edad As Integer;
  Read edad;
  If edad < 12 Then
    Write "Paga 5";
  Else
    Write "Paga 8";
  EndIf
EndAlgorithm

Algorithm Propina
  Define cuenta As Integer;
  Define amigos As Integer;
  Read cuenta;
  Read amigos;
  If amigos = 0 Then
    Write "No hay quien pague";
  Else
    Write "Cada uno paga: ", ceil((cuenta + cuenta Div 10) / amigos);
  EndIf
EndAlgorithm
